WITH with_latest AS (SELECT s.*, top1.salary FROM departments s LEFT JOIN LATERAL (SELECT c.salary FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) top1 ON TRUE), eligible AS (SELECT s.* FROM with_latest s WHERE EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.full_name LIKE '%Oliv%')), with_last AS (SELECT s.id, s.dept_name, s.location, latest.employee_salary FROM eligible s LEFT JOIN LATERAL (SELECT c.salary AS employee_salary FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE), eligible_departments AS (SELECT s.* FROM with_last s WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.manager_id IN (12, 14, 40))), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY employee_salary DESC, id) AS latest_rank FROM eligible_departments QUALIFY latest_rank = 1), kept AS (SELECT s.* FROM deduped s WHERE EXISTS (SELECT 1 FROM employees x WHERE x.dept_id = s.id AND x.is_remote = TRUE)), daily AS (SELECT CASE WHEN employee_salary >= 148000 THEN 'LARGE' ELSE 'SMALL' END AS employee_salary_tier, dept_name, SIZE(COLLECT_SET(location)) AS num_locations, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, COUNT(*) AS event_count, ROUND(AVG(employee_salary), 2) AS avg_employee_salary, PERCENTILE_APPROX(employee_salary, 0.5) AS employee_salary_p50, COUNT(*) FILTER (WHERE location = 'Chiang Mai') AS chiang_mai_rows FROM kept GROUP BY CASE WHEN employee_salary >= 148000 THEN 'LARGE' ELSE 'SMALL' END, dept_name HAVING COUNT(*) < 1000) SELECT employee_salary_tier, dept_name, event_count, avg_employee_salary, employee_salary_p50, chiang_mai_rows FROM daily ORDER BY chiang_mai_rows NULLS FIRST
